     * Fired the first time data is rendered into the grid. Use this event if you want to auto
     * resize columns based on their contents
     */
    fun onFirstDataRendered(event: FirstDataRenderedEvent)
    /**
     * The size of the grid `div` has changed. In other words, the grid was resized.
     */
    fun onGridSizeChanged(event: GridSizeChangedEvent)
    /**
     * Displayed rows have changed. Triggered after sort, filter or tree expand / collapse events.
     */
    fun onModelUpdated(event: ModelUpdatedEvent)
    /**
     * A row was removed from the DOM, for any reason. Use to clean up resources (if any) used by
     * the row.
     */
    fun onVirtualRowRemoved(event: VirtualRowRemovedEvent)
    /**
     * Which rows are rendered in the DOM has changed.
     */
    fun onViewportChanged(event: ViewportChangedEvent)
    /**
     * The body was scrolled horizontally or vertically.
     */
    fun onBodyScroll(event: BodyScrollEvent)
    /**
     * Main body of the grid has stopped scrolling, either horizontally or vertically.
     */
    fun onBodyScrollEnd(event: BodyScrollEndEvent)
    /**
     * When dragging starts. This could be any action that uses the grid's Drag and Drop service,
     * e.g. Column Moving, Column Resizing, Range Selection, Fill Handle, etc.
     */
    fun onDragStarted(event: DragStartedEvent)
    /**
     * When dragging stops. This could be any action that uses the grid's Drag and Drop service,
     * e.g. Column Moving, Column Resizing, Range Selection, Fill Handle, etc.
     */
    fun onDragStopped(event: DragStoppedEvent)
    /**
     * When dragging is cancelled stops. This is caused by pressing `Escape` while dragging elements
     * within the grid that uses the grid's Drag and Drop service, e.g. Column Moving, Column
     * Resizing, Range Selection, Fill Handle, etc.
     */
    fun onDragCancelled(event: DragCancelledEvent)
    /**
     * Grid state has been updated.
     */
    fun onStateUpdated(event: StateUpdatedEvent)
    /**
     * A development-time diagnostic - an error, warning or deprecation - was raised. Fires for
     * every diagnostic, whether or not it is also shown in the validation overlay or thrown by
     * `throwOn`, so tooling can react to it programmatically. Diagnostics raised before the grid is
     * created (e.g. a missing row model module) are reported to the console only, as no grid exists
     * to receive them. @agModule `ValidationModule`
     */
    fun onIssueRaised(event: IssueRaisedEvent)
    /**
     * Triggered every time the paging state changes. Some of the most common scenarios for this
     * event to be triggered are: - The page size changes. - The current shown page is changed. -
     * New data is loaded onto the grid.
     */
    fun onPaginationChanged(event: PaginationChangedEvent)
    /**
     * A drag has started, or dragging was already started and the mouse has re-entered the grid
     * having previously left the grid.
     */
    fun onRowDragEnter(event: RowDragEnterEvent)
    /**
     * The mouse has moved while dragging.
     */
    fun onRowDragMove(event: RowDragMoveEvent)
    /**
     * The mouse has left the grid while dragging.
     */
    fun onRowDragLeave(event: RowDragLeaveEvent)
    /**
     * The drag has finished over the grid.
     */
    fun onRowDragEnd(event: RowDragEndEvent)
    /**
     * The drag has been cancelled over the grid.
     */
    fun onRowDragCancel(event: RowDragCancelEvent)
    /**
     * Called by drag and drop when rows are dragged over another row to conditionally prevent
     * dropping the dragged row on the hovered row. The user can cancel the drop by returning
     * `false` or customize the operation by returning a `IsRowValidDropPositionResult`. @agModule
     * `RowDragModule`
     */
    var isRowValidDropPosition: IsRowValidDropPositionCallback?
    /**
     * The row resize has started (Row Numbers Feature)
     */
    fun onRowResizeStarted(event: RowResizeStartedEvent)
    /**
     * The row resize has ended (Row Numbers Feature)
     */
    fun onRowResizeEnded(event: RowResizeEndedEvent)
    /**
     * A row group column was added, removed or reordered.
     */
    fun onColumnRowGroupChanged(event: ColumnRowGroupChangedEvent)
    /**
     * A row group was opened or closed.
     */
    fun onRowGroupOpened(event: RowGroupOpenedEvent)
    /**
     * Fired when calling either of the API methods `expandAll()` or `collapseAll()`.
     */
    fun onExpandOrCollapseAll(event: ExpandOrCollapseAllEvent)
    /**
     * Exceeded the `pivotMaxGeneratedColumns` limit when generating columns.
     */
    fun onPivotMaxColumnsExceeded(event: PivotMaxColumnsExceededEvent)
    /**
     * The client has set new pinned row data into the grid.
     */
    fun onPinnedRowDataChanged(event: PinnedRowDataChangedEvent)
    /**
     * A row has been pinned to top or bottom, or unpinned.
     */
    fun onPinnedRowsChanged(event: PinnedRowsChangedEvent)
    /**
     * Client-Side Row Model only. The client has updated data for the grid by either a) setting new
     * Row Data or b) Applying a Row Transaction.
     */
    fun onRowDataUpdated(event: RowDataUpdatedEvent)
    /**
     * Async transactions have been applied. Contains a list of all transaction results.
     */
    fun onAsyncTransactionsFlushed(event: AsyncTransactionsFlushedEvent)
    /**
     * A server side store has finished refreshing.
     */
    fun onStoreRefreshed(event: StoreRefreshedEvent)
    /**
     * Header is focused.
     */
    fun onHeaderFocused(event: HeaderFocusedEvent)
    /**
     * Cell is clicked.
     */
    fun onCellClicked(event: CellClickedEvent)
    /**
     * Cell is double clicked.
     */
    fun onCellDoubleClicked(event: CellDoubleClickedEvent)
    /**
     * Cell is focused.
     */
    fun onCellFocused(event: CellFocusedEvent)
    /**
     * Mouse entered cell.
     */
    fun onCellMouseOver(event: CellMouseOverEvent)
    /**
     * Mouse left cell.
     */
    fun onCellMouseOut(event: CellMouseOutEvent)
    /**
     * Mouse down on cell.
     */
    fun onCellMouseDown(event: CellMouseDownEvent)
    /**
     * Row is clicked.
     */
    fun onRowClicked(event: RowClickedEvent)
    /**
     * Row is double clicked.
     */
    fun onRowDoubleClicked(event: RowDoubleClickedEvent)
    /**
     * Row is selected or deselected. The event contains the node in question, so call the node's
     * `isSelected()` method to see if it was just selected or deselected.
     */
    fun onRowSelected(event: RowSelectedEvent)
    /**
     * Row selection is changed. Use the `selectedNodes` field to get the list of selected nodes at
     * the time of the event. When using the SSRM, `selectedNodes` will be `null` when selecting all
     * nodes. Instead, refer to the `serverSideState` field.
     */
    fun onSelectionChanged(event: SelectionChangedEvent)
    /**
     * Cell is right clicked.
     */
    fun onCellContextMenu(event: CellContextMenuEvent)
    /**
     * A change to range selection has occurred. @deprecated v32.2 Use `onCellSelectionChanged`
     * instead
     */
    fun onRangeSelectionChanged(event: RangeSelectionChangedEvent)
    /**
     * A change to cell selection has occurred.
     */
    fun onCellSelectionChanged(event: CellSelectionChangedEvent)
    /**
     * A tooltip has been displayed
     */
    fun onTooltipShow(event: TooltipShowEvent?)
    /**
     * A tooltip was hidden
     */
    fun onTooltipHide(event: TooltipHideEvent?)
    /**
     * Sort has changed. The grid also listens for this and updates the model.
     */
    fun onSortChanged(event: SortChangedEvent)
}

/**
 * Determines the behaviour when selecting a group row. - When `'self'`, selects only the group row
 * itself. - When `'descendants'`, selecting a group row selects all its child rows. - When
 * `'filteredDescendants'`, selecting a group row selects all child rows that satisfy the currently
 * active filter.
 */
sealed external interface GroupSelectionMode

inline fun GroupSelectionMode(value: String): GroupSelectionMode = value.unsafeCast<GroupSelectionMode>()

object GroupSelectionModes {
    inline val self: GroupSelectionMode get() = GroupSelectionMode("self")
    inline val descendants: GroupSelectionMode get() = GroupSelectionMode("descendants")
    inline val filteredDescendants: GroupSelectionMode get() = GroupSelectionMode("filteredDescendants")
}

